DELIMITER $$
CREATE PROCEDURE sp_transfer(IN p_from CHAR(3),
  IN p_to CHAR(3), IN p_amt DECIMAL(10,2),
  OUT p_msg VARCHAR(20))
BEGIN
  DECLARE b DECIMAL(10,2) DEFAULT NULL;
  START TRANSACTION;
  UPDATE account SET balance = balance - p_amt
    WHERE id = p_from;
  SELECT balance INTO b FROM account
    WHERE id = p_from;
  IF b IS NULL OR b < 0 THEN
    ROLLBACK;
    SET p_msg = '转账失败';
  ELSE
    UPDATE account SET balance = balance + p_amt
      WHERE id = p_to;
    COMMIT;
    SET p_msg = '转账成功';
  END IF;
END $$
DELIMITER ;
CALL sp_transfer('A02', 'A01', 5000, @m);
SELECT @m;
